@attrs(repr=False, slots=True, unsafe_hash=True)
class _DeepMapping:
    key_validator = attrib(default=None, validator=optional(is_callable()))
    value_validator = attrib(default=None, validator=optional(is_callable()))
    mapping_validator = attrib(default=None, validator=optional(is_callable()))

    def __call__(self, inst, attr, value):
        """
        We use a callable class to be able to change the ``__repr__``.
        """
        if self.mapping_validator is not None:
            self.mapping_validator(inst, attr, value)

        if self.key_validator is None:
            for value_ in value.values():
                self.value_validator(inst, attr, value_)
        elif self.value_validator is None:
            for key in value:
                self.key_validator(inst, attr, key)
        else:
            for key in value:
                self.key_validator(inst, attr, key)
                self.value_validator(inst, attr, value[key])

    def __repr__(self):
        return f"<deep_mapping validator for objects mapping {self.key_validator!r} to {self.value_validator!r}>"


def deep_mapping(key_validator=None, value_validator=None, mapping_validator=None):
    """
    A validator that performs deep validation of a dictionary.

    Args:
        key_validator:
            Validator to apply to dictionary keys (optional).

        value_validator:
            Validator to apply to dictionary values (optional).

        mapping_validator:
            Validator to apply to top-level mapping attribute (optional).

    .. versionadded:: 19.1.0

    Raises:
        TypeError: if any sub-validators fail

        ValueError: if neither *key_validator* nor *value_validator* is provided
    """
    if key_validator is None and value_validator is None:
        msg = "At least one of key_validator or value_validator must be provided"
        raise ValueError(msg)

    return _DeepMapping(key_validator, value_validator, mapping_validator)

